package net.officefloor.hq.app.period;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.Map;

/** A sheet's period: a name unique on the sheet and the dates it runs from and to, both inclusive. */
@Entity
@Table(name = "period")
public class Period {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "from_date", nullable = false)
    private LocalDate from;

    @Column(name = "to_date", nullable = false)
    private LocalDate to;

    @Column(name = "closed", nullable = false)
    private boolean closed;

    /** Whether the period is soft-closed: its figures are fixed but claims dated in it can change. */
    @Column(name = "soft_closed", nullable = false)
    private boolean softClosed;

    /** The due-total fixed when the period was closed or soft-closed; null while it is open. */
    @Column(name = "closed_total")
    private BigDecimal closedTotal;

    /** Each person's due-total for the period fixed when it was closed, by person id; empty while it
     *  is open. A person not in it counts 0.00 for the closed period. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_total", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "total", nullable = false)
    private Map<Long, BigDecimal> personTotals = new HashMap<>();

    /** Each person's carried figure for the period fixed when it was closed or soft-closed, by person
     *  id; empty while it is open. A person not in it counts 0.00 for the closed period. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_carried", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "carried", nullable = false)
    private Map<Long, BigDecimal> personCarried = new HashMap<>();

    /** The most OPEN and PENDING claims a person may have in the period; null for no cap. */
    @Column(name = "claim_cap")
    private Integer cap;

    protected Period() {
    }

    public Period(String sheetId, String name, LocalDate from, LocalDate to) {
        this.sheetId = sheetId;
        this.name = name;
        this.from = from;
        this.to = to;
    }

    public Period(String sheetId, String name, LocalDate from, LocalDate to, Integer cap) {
        this(sheetId, name, from, to);
        this.cap = cap;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public LocalDate getFrom() {
        return from;
    }

    public LocalDate getTo() {
        return to;
    }

    public Integer getCap() {
        return cap;
    }

    public boolean isClosed() {
        return closed;
    }

    public boolean isSoftClosed() {
        return softClosed;
    }

    public BigDecimal getClosedTotal() {
        return closedTotal;
    }

    public Map<Long, BigDecimal> getPersonTotals() {
        return Map.copyOf(personTotals);
    }

    public Map<Long, BigDecimal> getPersonCarried() {
        return Map.copyOf(personCarried);
    }

    /** Close the period, fixing its due-total and each person's due-total and carried figure for it. */
    public void close(BigDecimal total, Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried) {
        this.closed = true;
        this.softClosed = false;
        fix(total, personTotals, personCarried);
    }

    /** Soft-close the period, fixing its due-total and each person's due-total and carried figure for
     *  it while claims dated in it can still change. */
    public void softClose(BigDecimal total, Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried) {
        this.softClosed = true;
        fix(total, personTotals, personCarried);
    }

    private void fix(BigDecimal total, Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried) {
        this.closedTotal = total;
        this.personTotals.clear();
        this.personTotals.putAll(personTotals);
        this.personCarried.clear();
        this.personCarried.putAll(personCarried);
    }

    /** Reopen the period: its due-total and carried figures are live again. */
    public void reopen() {
        this.closed = false;
        this.softClosed = false;
        this.closedTotal = null;
        this.personTotals.clear();
        this.personCarried.clear();
    }

    /** Whether the date falls in the period (inclusive). */
    public boolean contains(LocalDate date) {
        return !date.isBefore(from) && !date.isAfter(to);
    }

    /** Whether the period shares a day with the dates from and to (inclusive). */
    public boolean overlaps(LocalDate from, LocalDate to) {
        return !this.from.isAfter(to) && !from.isAfter(this.to);
    }
}
package net.officefloor.hq.app.period;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.NoSuchElementException;
import java.util.TreeMap;
import net.officefloor.hq.app.AsOf;
import net.officefloor.hq.app.SignedInUser;
import net.officefloor.hq.app.history.History;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/periods")
public class PeriodController {

    /** A period as the screen shows it; closedPersonTotals is each person's due-total for it fixed
     *  when it was closed, and closedPersonCarried each person's carried figure for it fixed then, by
     *  person id (both empty while it is open). */
    public record PeriodView(Long id, String name, LocalDate from, LocalDate to, boolean closed,
            boolean softClosed, String closedTotal, Map<Long, String> closedPersonTotals, Integer cap,
            Map<Long, String> closedPersonCarried) {
        static PeriodView of(Period period) {
            return new PeriodView(period.getId(), period.getName(), period.getFrom(), period.getTo(),
                    period.isClosed(), period.isSoftClosed(),
                    period.getClosedTotal() != null ? period.getClosedTotal().toPlainString() : null,
                    texts(period.getPersonTotals()), period.getCap(), texts(period.getPersonCarried()));
        }

        static PeriodView of(History.PeriodThen period, Integer cap) {
            return new PeriodView(period.id(), period.name(), period.from(), period.to(), period.closed(),
                    period.softClosed(), period.closedTotal() != null ? period.closedTotal().toPlainString() : null,
                    texts(period.personTotals()), cap, texts(period.personCarried()));
        }

        private static Map<Long, String> texts(Map<Long, BigDecimal> figures) {
            Map<Long, String> texts = new TreeMap<>();
            figures.forEach((id, figure) -> texts.put(id, figure.toPlainString()));
            return texts;
        }
    }

    /** A period: a name, its from and to dates, and the most OPEN and PENDING claims a person may
     *  have in it (null: no cap). */
    public record PeriodRequest(@NotBlank @Size(max = 200) String name,
            @NotNull LocalDate from, @NotNull LocalDate to, @Min(1) Integer cap) {
    }

    private final PeriodService service;

    public PeriodController(PeriodService service) {
        this.service = service;
    }

    /** The sheet's periods, the earliest first: as they stand now, or as they stood at the end of the
     *  screen's as-of date. */
    @GetMapping
    public List<PeriodView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(value = AsOf.HEADER, required = false) String asOfHeader) {
        LocalDate asOf = AsOf.parse(asOfHeader);
        if (asOf != null) {
            // A period's cap is fixed when it is added, so the period as it stood then has the cap it has now.
            Map<Long, Integer> caps = new HashMap<>();
            service.list(sheetId.trim()).forEach(period -> caps.put(period.getId(), period.getCap()));
            return service.listAsOf(sheetId.trim(), asOf).stream()
                    .map(period -> PeriodView.of(period, caps.get(period.id()))).toList();
        }
        return service.list(sheetId.trim()).stream().map(PeriodView::of).toList();
    }

    /** Add a period to the sheet. */
    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PeriodView add(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated PeriodRequest request) {
        return PeriodView.of(service.add(sheetId.trim(), SignedInUser.decode(user), request.name().trim(),
                request.from(), request.to(), request.cap()));
    }

    /** Monthly periods to generate: the dates whose months they run from and to; a blank date is the
     *  sheet's today. */
    public record GenerateRequest(LocalDate from, LocalDate to) {
    }

    /** How many periods a generate made. */
    public record GenerateView(int made) {
    }

    /** Generate one period per calendar month between two dates, leaving out months taken. */
    @PostMapping("/generate")
    public GenerateView generate(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody GenerateRequest request) {
        return new GenerateView(service.generate(sheetId.trim(), SignedInUser.decode(user), request.from(),
                request.to()));
    }

    /** A fiscal year to generate the monthly periods of: FY<year>. */
    public record GenerateFiscalYearRequest(@NotNull @Min(1) @Max(9998) Integer year) {
    }

    /** Generate the twelve monthly periods of a fiscal year, leaving out months taken. */
    @PostMapping("/generate-fy")
    public GenerateView generateFiscalYear(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody @Validated GenerateFiscalYearRequest request) {
        return new GenerateView(service.generateFiscalYear(sheetId.trim(), SignedInUser.decode(user),
                request.year()));
    }

    /** Close a period, fixing its due-total. */
    @PostMapping("/{name}/close")
    public PeriodView close(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable String name,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return PeriodView.of(service.close(sheetId.trim(), SignedInUser.decode(user), name));
    }

    /** Soft-close a period, fixing its figures while claims dated in it can still change. */
    @PostMapping("/{name}/soft-close")
    public PeriodView softClose(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable String name,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return PeriodView.of(service.softClose(sheetId.trim(), SignedInUser.decode(user), name));
    }

    /** Reopen a closed or soft-closed period, making its due-total live again; only a steward may. */
    @PostMapping("/{name}/reopen")
    public PeriodView reopen(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable String name,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return PeriodView.of(service.reopen(sheetId.trim(), SignedInUser.decode(user), name));
    }

    /** A period already closed is refused. */
    @ExceptionHandler(PeriodClosedException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public void closed() {
    }

    @ExceptionHandler(NoSuchElementException.class)
    @ResponseStatus(HttpStatus.NOT_FOUND)
    public void notFound() {
    }

    /** A name taken, dates running backwards, a period overlapping another, or a reopen by other
     *  than a steward or of a period not closed is refused. */
    @ExceptionHandler({PeriodRefusedException.class, DataIntegrityViolationException.class})
    @ResponseStatus(HttpStatus.CONFLICT)
    public void refused() {
    }

    /** A date that is not a real yyyy-mm-dd date is refused. */
    @ExceptionHandler(HttpMessageNotReadableException.class)
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public void unreadable() {
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface PeriodRepository extends JpaRepository<Period, Long> {

    /** The sheet's periods, the earliest first. */
    List<Period> findBySheetIdOrderByFromAsc(String sheetId);

    /** Whether a period on the sheet has this name, ignoring case. */
    @Query("select count(p) > 0 from Period p where p.sheetId = :sheetId and lower(p.name) = lower(:name)")
    boolean nameInUse(@Param("sheetId") String sheetId, @Param("name") String name);

    /** The sheet's period by name. */
    Optional<Period> findBySheetIdAndName(String sheetId, String name);

    /** Whether a closed period on the sheet contains the date. */
    @Query("select count(p) > 0 from Period p where p.sheetId = :sheetId and p.closed = true"
            + " and p.from <= :date and p.to >= :date")
    boolean closedOn(@Param("sheetId") String sheetId, @Param("date") LocalDate date);

    /** Whether a soft-closed period on the sheet contains the date. */
    @Query("select count(p) > 0 from Period p where p.sheetId = :sheetId and p.softClosed = true"
            + " and p.from <= :date and p.to >= :date")
    boolean softClosedOn(@Param("sheetId") String sheetId, @Param("date") LocalDate date);
}
